@using sv_bb631e864d054bbe82e836022a545778.Models

<div class="personal-info-step">
    <h4>Personal Information</h4>

    <div class="mb-3">
        <label class="form-label">Full Name *</label>
        <input type="text" class="form-control" @bind="FullName" @bind:event="oninput" />
    </div>

    <div class="mb-3">
        <label class="form-label">Email *</label>
        <input type="email" class="form-control" @bind="Email" @bind:event="oninput" />
        @if (!string.IsNullOrEmpty(emailError))
        {
            <div class="text-danger mt-1">@emailError</div>
        }
    </div>

    <div class="mb-3">
        <label class="form-label">Phone *</label>
        <input type="tel" class="form-control" @bind="Phone" @bind:event="oninput" />
    </div>

    <div class="mb-3">
        <label class="form-label">Address *</label>
        <textarea class="form-control" rows="2" @bind="Address" @bind:event="oninput"></textarea>
    </div>

    @if (!string.IsNullOrEmpty(validationError))
    {
        <div class="alert alert-danger">@validationError</div>
    }

    <div class="d-flex justify-content-end">
        <button class="btn btn-primary" @onclick="HandleNext" disabled="@isValidating">
            @if (isValidating)
            {
                <span class="spinner-border spinner-border-sm me-1"></span>
            }
            Next
        </button>
    </div>
</div>

@code {
    [Parameter] public PersonalInfo? Value { get; set; }
    [Parameter] public EventCallback<PersonalInfo> OnNext { get; set; }
    [Parameter] public IApplicationService ApplicationService { get; set; } = default!;

    private string FullName { get; set; } = "";
    private string Email { get; set; } = "";
    private string Phone { get; set; } = "";
    private string Address { get; set; } = "";

    private string? validationError;
    private string? emailError;
    private bool isValidating;

    protected override void OnParametersSet()
    {
        if (Value is not null)
        {
            FullName = Value.FullName;
            Email = Value.Email;
            Phone = Value.Phone;
            Address = Value.Address;
        }
    }

    private async Task HandleNext()
    {
        validationError = null;
        emailError = null;

        if (string.IsNullOrWhiteSpace(FullName) || string.IsNullOrWhiteSpace(Email) ||
            string.IsNullOrWhiteSpace(Phone) || string.IsNullOrWhiteSpace(Address))
        {
            validationError = "All fields are required.";
            return;
        }

        isValidating = true;
        try
        {
            var emailValid = await ApplicationService.ValidateEmailAsync(Email);
            if (!emailValid)
            {
                emailError = "The email address is not valid.";
                return;
            }

            await OnNext.InvokeAsync(new PersonalInfo(FullName.Trim(), Email.Trim(), Phone.Trim(), Address.Trim()));
        }
        finally
        {
            isValidating = false;
        }
    }
}

@using sv_bb631e864d054bbe82e836022a545778.Models

<div class="work-entry-editor card mb-3">
    <div class="card-body">
        <div class="d-flex justify-content-between align-items-center mb-2">
            <h6 class="card-title mb-0">Position @(Index + 1)</h6>
            @if (CanRemove)
            {
                <button class="btn btn-outline-danger btn-sm" @onclick="HandleRemove">Remove</button>
            }
        </div>

        <div class="row">
            <div class="col-md-6 mb-2">
                <label class="form-label">Company Name *</label>
                <input type="text" class="form-control" value="@Company" @oninput="e => { Company = e.Value?.ToString() ?? \"\"; NotifyChanged(); }" />
            </div>
            <div class="col-md-6 mb-2">
                <label class="form-label">Job Title *</label>
                <input type="text" class="form-control" value="@Title" @oninput="e => { Title = e.Value?.ToString() ?? \"\"; NotifyChanged(); }" />
            </div>
        </div>

        <div class="row">
            <div class="col-md-4 mb-2">
                <label class="form-label">Start Date *</label>
                <input type="date" class="form-control" value="@StartDate?.ToString("yyyy-MM-dd")" @onchange="e => { StartDate = DateTime.TryParse(e.Value?.ToString(), out var d) ? d : null; NotifyChanged(); }" />
            </div>
            <div class="col-md-4 mb-2">
                <label class="form-label">End Date</label>
                <input type="date" class="form-control" value="@EndDate?.ToString("yyyy-MM-dd")" disabled="@IsCurrent"
                       @onchange="e => { EndDate = DateTime.TryParse(e.Value?.ToString(), out var d) ? d : null; NotifyChanged(); }" />
            </div>
            <div class="col-md-4 mb-2 d-flex align-items-end">
                <div class="form-check">
                    <input class="form-check-input" type="checkbox" checked="@IsCurrent" @onchange="e => { IsCurrent = (bool)(e.Value ?? false); if (IsCurrent) EndDate = null; NotifyChanged(); }" />
                    <label class="form-check-label">Currently working here</label>
                </div>
            </div>
        </div>

        <div class="mb-2">
            <label class="form-label">Description</label>
            <textarea class="form-control" rows="3" @oninput="e => { Description = e.Value?.ToString() ?? \"\"; NotifyChanged(); }">@Description</textarea>
        </div>
    </div>
</div>

@code {
    [Parameter] public int Index { get; set; }
    [Parameter] public WorkEntry? Value { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback<WorkEntry> OnChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private string Company { get; set; } = "";
    private string Title { get; set; } = "";
    private DateTime? StartDate { get; set; }
    private DateTime? EndDate { get; set; }
    private bool IsCurrent { get; set; }
    private string Description { get; set; } = "";

    protected override void OnParametersSet()
    {
        if (Value is not null)
        {
            Company = Value.Company;
            Title = Value.Title;
            StartDate = Value.StartDate;
            EndDate = Value.EndDate;
            IsCurrent = Value.EndDate is null && !string.IsNullOrEmpty(Value.Company);
            Description = Value.Description;
        }
    }

    private void NotifyChanged()
    {
        var entry = new WorkEntry(Company, Title, StartDate ?? DateTime.Today, IsCurrent ? null : EndDate, Description);
        OnChanged.InvokeAsync(entry);
    }

    private async Task HandleRemove()
    {
        await OnRemove.InvokeAsync();
    }
}

@using sv_bb631e864d054bbe82e836022a545778.Models

<div class="work-history-step">
    <h4>Work History</h4>

    @for (int i = 0; i < entries.Count; i++)
    {
        var index = i;
        <WorkEntryEditor Index="index"
                         Value="entries[index]"
                         CanRemove="entries.Count > 1"
                         OnChanged="e => UpdateEntry(index, e)"
                         OnRemove="() => RemoveEntry(index)" />
    }

    <button class="btn btn-outline-secondary mb-3" @onclick="AddEntry">
        + Add Another Position
    </button>

    @if (!string.IsNullOrEmpty(validationError))
    {
        <div class="alert alert-danger">@validationError</div>
    }

    <div class="d-flex justify-content-between">
        <button class="btn btn-secondary" @onclick="HandleBack">Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public WorkHistory? Value { get; set; }
    [Parameter] public EventCallback<WorkHistory> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private List<WorkEntry> entries = new();
    private string? validationError;

    protected override void OnParametersSet()
    {
        if (Value is not null && Value.Entries.Count > 0)
        {
            entries = Value.Entries.ToList();
        }
        else if (entries.Count == 0)
        {
            entries.Add(new WorkEntry("", "", DateTime.Today, null, ""));
        }
    }

    private void AddEntry()
    {
        entries.Add(new WorkEntry("", "", DateTime.Today, null, ""));
    }

    private void RemoveEntry(int index)
    {
        if (entries.Count > 1)
        {
            entries.RemoveAt(index);
        }
    }

    private void UpdateEntry(int index, WorkEntry entry)
    {
        if (index < entries.Count)
        {
            entries[index] = entry;
        }
    }

    private async Task HandleNext()
    {
        validationError = null;

        foreach (var entry in entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title))
            {
                validationError = "Each position requires at least a company name and job title.";
                return;
            }
        }

        await OnNext.InvokeAsync(new WorkHistory(entries.ToList()));
    }

    private async Task HandleBack()
    {
        await OnBack.InvokeAsync();
    }
}

