@using sv_bb631e864d054bbe82e836022a545778.Models

<div class="references-step">
    <h4>References</h4>
    <p class="text-muted">Please provide 2-3 professional references.</p>

    @for (int i = 0; i < references.Count; i++)
    {
        var index = i;
        <ReferenceEditor Index="index"
                         Value="references[index]"
                         CanRemove="references.Count > 2"
                         OnChanged="e => UpdateReference(index, e)"
                         OnRemove="() => RemoveReference(index)" />
