{"file_text": "@using sv_bb631e864d054bbe82e836022a545778.Models

<div class="review-step">
    <h4>Review & Submit</h4>
    <p class="text-muted">Please review your application before submitting.</p>

    @if (IsSubmitted)
    {
        <div class="alert alert-success">
            <h5>Application Submitted Successfully!</h5>
            <p>Your application ID is: <strong>@ApplicationId</strong></p>
            <p>Thank you for applying. We will review your application and get back to you soon.</p>
        </div>
    }
    else
    {
        <div class="card mb-3">
            <div class="card-header d-flex justify-content-between align-items-center">
                <strong>Personal Information</strong>
                <button class="btn btn-link btn-sm" @onclick="() => OnEditStep.InvokeAsync(0)">Edit</button>
            </div>
            <div class="card-body">
                @if (Personal is not null)
                {
                    <p><strong>Name:</strong> @Personal.FullName</p>
                    <p><strong>Email:</strong> @Personal.Email</p>
                    <p><strong>Phone:</strong> @Personal.Phone</p>
                    <p class="mb-0"><strong>Address:</strong> @Personal.Address</p>
                }
            </div>
        </div>

        <div class="card mb-3">
            <div class="card-header d-flex justify-content-between align-items-center">
                <strong>Work History</strong>
                <button class="btn btn-link btn-sm" @onclick="() => OnEditStep.InvokeAsync(1)">Edit</button>
            </div>
            <div class="card-body">
                @if (Work is not null)
                {
                    @foreach (var entry in Work.Entries)
                    {
                        <div class="mb-3 pb-2 border-bottom">
                            <p class="mb-1"><strong>@entry.Title</strong> at @entry.Company</p>
                            <p class="mb-1 text-muted">
                                @entry.StartDate.ToString("MMM yyyy") &ndash;
                                @(entry.EndDate?.ToString("MMM yyyy") ?? "Present")
                            </p>
                            @if (!string.IsNullOrWhiteSpace(entry.Description))
                            {
                                <p class="mb-0">@entry.Description</p>
                            }
                        </div>
                    }
                }
            </div>
        </div>

        <div class="card mb-3">
            <div class="card-header d-flex justify-content-between align-items-center">
                <strong>References</strong>
                <button class="btn btn-link btn-sm" @onclick="() => OnEditStep.InvokeAsync(2)">Edit</button>
            </div>
            <div class="card-body">
                @if (References is not null)
                {
                    @foreach (var r in References)
                    {
                        <div class="mb-2">
                            <strong>@r.Name</strong> (@r.Relationship) &mdash; @r.Email, @r.Phone
                        </div>
                    }
                }
            </div>
        </div>

        <div class="card mb-3">
            <div class="card-header d-flex justify-content-between align-items-center">
                <strong>Cover Letter</strong>
                <button class="btn btn-link btn-sm" @onclick="() => OnEditStep.InvokeAsync(3)">Edit</button>
            </div>
            <div class="card-body">
                <p style="white-space: pre-wrap;">@CoverLetter</p>
            </div>
        </div>

        @if (!string.IsNullOrEmpty(submitError))
        {
            <div class="alert alert-danger">@submitError</div>
        }

        <div class="d-flex justify-content-between">
            <button class="btn btn-secondary" @onclick="HandleBack">Back</button>
            <button class="btn btn-success btn-lg" @onclick="HandleSubmit" disabled="@isSubmitting">
                @if (isSubmitting)
                {
                    <span class="spinner-border spinner-border-sm me-1"></span>
                }
                Submit Application
            </button>
        </div>
    }
</div>

@code {
    [Parameter] public PersonalInfo? Personal { get; set; }
    [Parameter] public WorkHistory? Work { get; set; }
    [Parameter] public List<Reference>? References { get; set; }
    [Parameter] public string? CoverLetter { get; set; }
    [Parameter] public EventCallback<int> OnEditStep { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public IApplicationService ApplicationService { get; set; } = default!;

    private bool isSubmitting;
    private bool IsSubmitted;
    private int ApplicationId;
    private string? submitError;

    private async Task HandleSubmit()
    {
        if (Personal is null || Work is null || References is null || CoverLetter is null)
            return;

        isSubmitting = true;
        submitError = null;

        try
        {
            var application = new JobApplication(Personal, Work, References, CoverLetter);
            ApplicationId = await ApplicationService.SubmitApplicationAsync(application);
            IsSubmitted = true;
        }
        catch (Exception ex)
        {
            submitError = $"An error occurred while submitting: {ex.Message}";
        }
        finally
        {
            isSubmitting = false;
        }
    }

    private async Task HandleBack()
    {
        await OnBack.InvokeAsync();
    }
}
