@using sv_bb631e864d054bbe82e836022a545778.Models

<div class="personal-info-step">
    <h4>Personal Information</h4>

    <div class="mb-3">
        <label class="form-label">Full Name *</label>
        <input type="text" class="form-control" @bind="FullName" @bind:event="oninput" />
    </div>

    <div class="mb-3">
        <label class="form-label">Email *</label>
        <input type="email" class="form-control" @bind="Email" @bind:event="oninput" />
        @if (!string.IsNullOrEmpty(emailError))
        {
            <div class="text-danger mt-1">@emailError</div>
        }
    </div>

    <div class="mb-3">
        <label class="form-label">Phone *</label>
        <input type="tel" class="form-control" @bind="Phone" @bind:event="oninput" />
    </div>

    <div class="mb-3">
        <label class="form-label">Address *</label>
        <textarea class="form-control" rows="2" @bind="Address" @bind:event="oninput"></textarea>
    </div>

    @if (!string.IsNullOrEmpty(validationError))
    {
        <div class="alert alert-danger">@validationError</div>
    }

    <div class="d-flex justify-content-end">
        <button class="btn btn-primary" @onclick="HandleNext" disabled="@isValidating">
            @if (isValidating)
            {
                <span class="spinner-border spinner-border-sm me-1"></span>
            }
            Next
        </button>
    </div>
</div>

@code {
    [Parameter] public PersonalInfo? Value { get; set; }
    [Parameter] public EventCallback<PersonalInfo> OnNext { get; set; }
    [Parameter] public IApplicationService ApplicationService { get; set; } = default!;

    private string FullName { get; set; } = "";
    private string Email { get; set; } = "";
    private string Phone { get; set; } = "";
    private string Address { get; set; } = "";

    private string? validationError;
    private string? emailError;
    private bool isValidating;

    protected override void OnParametersSet()
    {
        if (Value is not null)
        {
            FullName = Value.FullName;
            Email = Value.Email;
            Phone = Value.Phone;
            Address = Value.Address;
        }
    }

    private async Task HandleNext()
    {
        validationError = null;
        emailError = null;

        if (string.IsNullOrWhiteSpace(FullName) || string.IsNullOrWhiteSpace(Email) ||
            string.IsNullOrWhiteSpace(Phone) || string.IsNullOrWhiteSpace(Address))
        {
            validationError = "All fields are required.";
            return;
        }

        isValidating = true;
        try
        {
            var emailValid = await ApplicationService.ValidateEmailAsync(Email);
            if (!emailValid)
            {
                emailError = "The email address is not valid.";
                return;
            }

            await OnNext.InvokeAsync(new PersonalInfo(FullName.Trim(), Email.Trim(), Phone.Trim(), Address.Trim()));
        }
        finally
        {
            isValidating = false;
        }
    }
}

