@using sv_bb631e864d054bbe82e836022a545778.Models

<div class="work-history-step">
    <h4>Work History</h4>

    @for (int i = 0; i < entries.Count; i++)
    {
        var index = i;
        <WorkEntryEditor Index="index"
                         Value="entries[index]"
                         CanRemove="entries.Count > 1"
                         OnChanged="e => UpdateEntry(index, e)"
                         OnRemove="() => RemoveEntry(index)" />
    }

    <button class="btn btn-outline-secondary mb-3" @onclick="AddEntry">
        + Add Another Position
    </button>

    @if (!string.IsNullOrEmpty(validationError))
    {
        <div class="alert alert-danger">@validationError</div>
    }

    <div class="d-flex justify-content-between">
        <button class="btn btn-secondary" @onclick="HandleBack">Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public WorkHistory? Value { get; set; }
    [Parameter] public EventCallback<WorkHistory> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private List<WorkEntry> entries = new();
    private string? validationError;

    protected override void OnParametersSet()
    {
        if (Value is not null && Value.Entries.Count > 0)
        {
            entries = Value.Entries.ToList();
        }
        else if (entries.Count == 0)
        {
            entries.Add(new WorkEntry("", "", DateTime.Today, null, ""));
        }
    }

    private void AddEntry()
    {
        entries.Add(new WorkEntry("", "", DateTime.Today, null, ""));
    }

    private void RemoveEntry(int index)
    {
        if (entries.Count > 1)
        {
            entries.RemoveAt(index);
        }
    }

    private void UpdateEntry(int index, WorkEntry entry)
    {
        if (index < entries.Count)
        {
            entries[index] = entry;
        }
    }

    private async Task HandleNext()
    {
        validationError = null;

        foreach (var entry in entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title))
            {
                validationError = "Each position requires at least a company name and job title.";
                return;
            }
        }

        await OnNext.InvokeAsync(new WorkHistory(entries.ToList()));
    }

    private async Task HandleBack()
    {
        await OnBack.InvokeAsync();
    }
}

