@using sv_bb631e864d054bbe82e836022a545778.Models

<div class="references-step">
    <h4>References</h4>
    <p class="text-muted">Please provide 2-3 professional references.</p>

    @for (int i = 0; i < references.Count; i++)
    {
        var index = i;
        <ReferenceEditor Index="index"
                         Value="references[index]"
                         CanRemove="references.Count > 2"
                         OnChanged="e => UpdateReference(index, e)"
                         OnRemove="() => RemoveReference(index)" />
    }

    @if (references.Count < 3)
    {
        <button class="btn btn-outline-secondary mb-3" @onclick="AddReference">
            + Add Reference
        </button>
    }

    @if (!string.IsNullOrEmpty(validationError))
    {
        <div class="alert alert-danger">@validationError</div>
    }

    <div class="d-flex justify-content-between">
        <button class="btn btn-secondary" @onclick="HandleBack">Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<Reference>? Value { get; set; }
    [Parameter] public EventCallback<List<Reference>> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private List<Reference> references = new();
    private string? validationError;

    protected override void OnParametersSet()
    {
        if (Value is not null && Value.Count > 0)
        {
            references = Value.ToList();
        }
        else if (references.Count == 0)
        {
            references.Add(new Reference("", "", "", ""));
            references.Add(new Reference("", "", "", ""));
        }
    }

    private void AddReference()
    {
        if (references.Count < 3)
        {
            references.Add(new Reference("", "", "", ""));
        }
    }

    private void RemoveReference(int index)
    {
        if (references.Count > 2)
        {
            references.RemoveAt(index);
        }
    }

    private void UpdateReference(int index, Reference reference)
    {
        if (index < references.Count)
        {
            references[index] = reference;
        }
    }

    private async Task HandleNext()
    {
        validationError = null;

        foreach (var r in references)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship) ||
                string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
            {
                validationError = "All reference fields are required.";
                return;
            }
        }

        await OnNext.InvokeAsync(references.ToList());
    }

    private async Task HandleBack()
    {
        await OnBack.InvokeAsync();
    }
}

